<template>
  <div class="app-container catalog">
    <div class="heading"><div><h2>模型管理</h2><p>先配置供应商和凭据，再保存模型的能力与价格版本。</p></div><el-tag type="info">多厂商模型目录</el-tag></div>
    <el-alert title="配置用于正式模型执行" description="本页保存和检查配置不会调用模型，也不证明真实 Key 有效。用户在创作端确认报价后执行；旧任务继续使用原模式和固定版本。" type="info" :closable="false" show-icon />
    <el-alert v-if="!ready" title="主密钥未配置，当前只读。请配置独立 keyringFile 后重启 API。" type="warning" :closable="false" class="notice" />
    <el-alert v-if="storageWarning" :title="storageWarning" type="warning" :closable="false" class="notice" />
    <el-alert v-if="pending" title="有一项提交待确认" type="warning" :closable="false" class="notice"><p>{{ pending.label }} · {{ pending.requestId }}</p><p>只保存目标、编号和版本；密钥不保存。先核对，重试须填写原内容并沿用原编号。</p><el-button :loading="checking" @click="checkPending">核对原操作</el-button><el-button @click="recoverPending">重填原操作</el-button></el-alert>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="notice" />
    <el-tabs v-model="tab" @tab-change="changeTab">
      <el-tab-pane v-if="has('podAdmin:model:list')" label="模型目录" name="models" />
      <el-tab-pane v-if="has('podAdmin:provider:list')" label="供应商与凭据" name="providers" />
      <el-tab-pane v-if="has('podAdmin:model:query')" label="默认模型" name="defaults" />
    </el-tabs>
    <template v-if="tab !== 'defaults'">
      <el-form inline class="query" @submit.prevent="search"><el-form-item label="名称"><el-input v-model="query.name" clearable /></el-form-item><el-form-item v-if="tab === 'models'" label="类型"><el-select v-model="query.kind" clearable placeholder="全部" style="width:110px"><el-option label="文字" value="text" /><el-option label="图片" value="image" /></el-select></el-form-item><el-form-item v-if="tab === 'models' && has('podAdmin:provider:list')" label="厂商"><el-select v-model="query.providerId" filterable remote clearable :remote-method="name => searchOptions('providerId',name)" @visible-change="open => open && searchOptions('providerId')" placeholder="全部厂商" style="width:190px"><el-option v-for="item in options.providerId || []" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部" style="width:110px"><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">查询</el-button><el-button v-if="canEdit" :disabled="blocked" @click="open(tab === 'providers' ? 'provider.create' : 'model.create')">{{ tab === 'providers' ? '新建供应商' : '新建模型' }}</el-button></el-form-item></el-form>
      <el-table v-loading="loading" :data="rows" :empty-text="tab === 'providers' ? '暂无供应商，先新建供应商并配置凭据。' : '暂无模型，先配置供应商，再新建模型和版本。'">
        <el-table-column label="名称 / 编码" min-width="170"><template #default="{row}"><strong>{{ row.name }}</strong><div class="muted">{{ row.code }} · #{{ row.modelId || row.providerId }}</div></template></el-table-column>
        <el-table-column v-if="tab === 'providers'" prop="endpoint" label="接口 Base URL" min-width="220" show-overflow-tooltip />
        <el-table-column v-else prop="providerName" label="供应商" min-width="130" />
        <el-table-column label="配置" min-width="150"><template #default="{row}"><template v-if="tab === 'providers'">{{ row.credentialConfigured ? `凭据 v${row.credentialVersion}` : '未配凭据' }}<div class="muted">{{ row.adapterKind }} · {{ row.credentialSourceType === 'env' ? '环境引用' : row.credentialConfigured ? '加密保存' : row.region }}</div></template><template v-else>{{ row.kind === 'text' ? '文字' : '图片' }} · {{ row.currentVersion === '0' ? '未建版本' : `v${row.currentVersion}` }}<div class="muted">{{ row.visible ? '可展示' : '隐藏' }} · 排序 {{ row.sort }}</div></template></template></el-table-column>
        <el-table-column label="配置状态" min-width="230"><template #default="{row}"><el-tag :type="configurationState(row,tab === 'providers').type">{{ configurationState(row,tab === 'providers').label }}</el-tag><div class="muted">{{ configurationState(row,tab === 'providers').detail }}</div></template></el-table-column>
        <el-table-column label="操作" min-width="320"><template #default="{row}">
          <el-button v-if="canEdit" link type="primary" :disabled="blocked" @click="open(tab === 'providers' ? 'provider.update' : 'model.update',row)">编辑</el-button>
          <template v-if="tab === 'providers'"><el-button v-if="has('podAdmin:provider:credential')" link type="primary" :disabled="blocked" @click="open('provider.credential',row)">{{ row.credentialConfigured ? '轮换凭据' : '配置凭据' }}</el-button></template>
          <template v-else><el-button v-if="has('podAdmin:model:query')" link type="primary" @click="showVersions(row)">版本</el-button><el-button v-if="canEdit" link type="primary" :disabled="blocked" @click="open('model.version',row)">新版本</el-button><el-button v-if="has('podAdmin:model:check')" link type="primary" @click="checkModel(row)">检查配置</el-button></template>
          <el-button v-if="canEdit" link :type="row.status === 'enabled' ? 'warning' : 'primary'" :disabled="blocked" @click="open(tab === 'providers' ? 'provider.status' : 'model.status',row)">{{ row.status === 'enabled' ? '停用' : '启用' }}</el-button>
        </template></el-table-column>
      </el-table>
      <pagination v-show="total > 0 && !error" v-model:page="page" v-model:limit="size" :total="total" @pagination="loadList" />
    </template>
    <template v-else><p class="muted">用于正式创作；用户还须获得对应模型授权。仅可选择已启用供应商下有有效版本的启用模型。</p><el-descriptions v-if="defaults" :column="1" border><el-descriptions-item label="平台版本">{{ defaults.revision }}</el-descriptions-item><el-descriptions-item label="默认文字模型">{{ defaults.textModelId || '未设置' }}</el-descriptions-item><el-descriptions-item label="默认图片模型">{{ defaults.imageModelId || '未设置' }}</el-descriptions-item><el-descriptions-item label="正式模式">{{ defaults.managedEnabled ? '已启用' : '未启用' }}</el-descriptions-item></el-descriptions><el-button v-if="canEdit" type="primary" class="notice" :disabled="blocked || !defaults" @click="open('defaults.update',defaults)">选择默认模型</el-button></template>

    <el-dialog v-model="dialog" :title="labels[op]" width="720px" :close-on-click-modal="false" :before-close="closeDialog" @closed="clearSecret">
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="notice" />
      <el-alert v-if="op === 'provider.credential'" title="凭据只写不读，提交后清空输入；轮换新增版本，保留历史密文。" type="warning" :closable="false" class="notice" />
      <el-alert v-if="op === 'model.version'" title="保存即新增不可变版本，并设为当前版本。成本与点数独立记账；本步骤只保存规则。" type="info" :closable="false" class="notice" />
      <el-alert v-if="op.endsWith('.status')" :title="`将${form.status === 'enabled' ? '启用' : '停用'}：${form.name}`" description="不会删除旧版本或改写原 qwen 任务；引用此记录的默认值保留，后续执行会重新检查可用性。" type="warning" :closable="false" class="notice" />
      <el-form label-width="145px" @submit.prevent="submit">
        <el-form-item v-for="field in fields" :key="field.key" :label="field.label" :for="'catalog-field-'+field.key" :required="field.required" :error="fieldErrors[field.key]">
          <el-select v-if="field.type === 'select'" v-model="form[field.key]" :id="'catalog-field-'+field.key" :clearable="field.clearable" filterable style="width:100%" @change="fieldChanged(field.key)"><el-option v-for="option in field.options" :key="option.value" :label="option.label" :value="option.value" :disabled="option.disabled" /></el-select>
          <el-select v-else-if="field.type === 'remote'" v-model="form[field.key]" filterable remote :clearable="field.clearable" :remote-method="name => searchOptions(field.key,name)" :loading="optionLoading" placeholder="输入名称搜索，最多显示 20 条" style="width:100%" @change="fieldChanged(field.key)"><el-option v-for="option in options[field.key] || []" :key="option.value" :label="option.label" :value="option.value" :disabled="option.disabled" /></el-select>
          <el-input-number v-else-if="field.type === 'number'" v-model="form[field.key]" :min="field.min" :max="field.max" :precision="0" />
          <el-switch v-else-if="field.type === 'switch'" v-model="form[field.key]" />
          <el-checkbox-group v-else-if="field.type === 'ratios'" v-model="form.ratios"><el-checkbox v-for="r in ratios" :key="r" :value="r">{{ r }}</el-checkbox></el-checkbox-group>
          <div v-else-if="field.type === 'note'" class="muted">{{ field.text }} <a v-if="field.source" :href="field.source" target="_blank" rel="noopener noreferrer">官方来源</a></div>
          <el-input v-else :id="'catalog-field-'+field.key" v-model="form[field.key]" :aria-invalid="!!fieldErrors[field.key]" :readonly="field.readonly" :type="field.key === 'secret' ? 'password' : 'text'" :autocomplete="field.key === 'secret' ? 'new-password' : 'off'" :maxlength="field.maxlength || 200" :placeholder="field.placeholder" :inputmode="field.decimal ? 'decimal' : field.numeric ? 'numeric' : 'text'" />
          <div v-if="field.hint" class="muted hint">{{ field.hint }}</div>
        </el-form-item>
        <el-form-item label="操作原因" required><el-input v-model="form.reason" maxlength="200" placeholder="只写业务原因，不填写密码或密钥" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="saving" @click="clearSecret();++dialogRequest;dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!ready" @click="submit">{{ pending ? '沿用原编号提交' : '确认保存' }}</el-button></template>
    </el-dialog>
    <el-dialog v-model="versionsOpen" :title="`${versionModel?.name || ''} · 历史版本`" width="900px"><el-alert v-if="versionsError" :title="versionsError" type="error" :closable="false" /><el-table v-loading="versionsLoading" :data="versions" empty-text="尚无版本"><el-table-column type="expand"><template #default="{row}"><el-descriptions :column="1" border><el-descriptions-item label="接口 Base URL">{{ row.endpoint }}</el-descriptions-item><el-descriptions-item label="能力">{{ capabilityLabel(row.capabilities) }}</el-descriptions-item><el-descriptions-item label="估算成本">{{ rateLabel(row.costRule,versionModel?.kind) }}</el-descriptions-item><el-descriptions-item label="正式点数">{{ rateLabel(row.pointRule,versionModel?.kind) }}</el-descriptions-item><el-descriptions-item label="规格摘要">{{ row.specHash }}</el-descriptions-item></el-descriptions></template></el-table-column><el-table-column prop="version" label="版本" width="70" /><el-table-column prop="officialModelId" label="官方模型" min-width="170" /><el-table-column prop="adapterKind" label="协议" min-width="110" /><el-table-column prop="timeoutSeconds" label="超时 / 秒" width="100" /><el-table-column prop="createTime" label="保存时间" min-width="170" /></el-table><pagination v-show="versionTotal > 0 && !versionsError" v-model:page="versionPage" v-model:limit="versionSize" :total="versionTotal" @pagination="loadVersions" /></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, reactive, ref, nextTick } from 'vue'
import { ElMessage } from 'element-plus'
import useUserStore from '@/store/modules/user'
import { catalogList, catalogGet, catalogVersions, catalogDefaults, catalogWrite, catalogAction, catalogCheck } from '@/api/pod/admin'
import { catalogFields, catalogPayload, readPending, pendingMetadata, capabilityLabel, rateLabel, providerProfiles, providerProfile, providerSupportsImages, modelPresets, applyModelPreset, modelExamplesFor, configurationState, catalogFieldErrors, microsToYuan } from '@/utils/pod-catalog'

const user = useUserStore(), has = permission => user.podAdmin?.permissions?.includes(permission)
const ready = computed(() => !!user.podAdmin?.catalogWrites)
const tab = ref(has('podAdmin:model:list') ? 'models' : has('podAdmin:provider:list') ? 'providers' : 'defaults')
const query = reactive({name:'',kind:'',status:'',providerId:''}), rows=ref([]), total=ref(0), page=ref(1), size=ref(10), loading=ref(false), error=ref(''), defaults=ref(null)
const dialog=ref(false), op=ref(''), form=ref({}), formError=ref(''), fieldErrors=ref({}), saving=ref(false), checking=ref(false), options=reactive({}), optionLoading=ref(false)
const versionsOpen=ref(false), versions=ref([]), versionModel=ref(null), versionPage=ref(1), versionSize=ref(10), versionTotal=ref(0), versionsLoading=ref(false), versionsError=ref('')
const ratios=['1:1','3:4','4:3','9:16','16:9']
const labels={'provider.create':'新建供应商','provider.update':'编辑供应商','provider.credential':'配置 / 轮换凭据','provider.status':'供应商状态','model.create':'新建模型','model.update':'修改模型信息','model.version':'保存模型新版本','model.status':'模型状态','defaults.update':'选择默认模型'}
const pendingKey=`pod-admin.catalog.pending.${user.id}`, pending=ref(null), storageWarning=ref('')
try{pending.value=readPending(sessionStorage.getItem(pendingKey))}catch{storageWarning.value='浏览器无法读取操作记录；可查看目录，提交前必须能够保存操作编号。'}
const blocked=computed(()=>!ready.value || !!pending.value || saving.value), canEdit=computed(()=>has(tab.value==='providers'?'podAdmin:provider:edit':'podAdmin:model:edit'))
const fields=computed(()=>catalogFields(op.value,form.value))
let listRequest=0, versionRequest=0, dialogRequest=0
const optionRequests={}
async function loadList(){const request=++listRequest;loading.value=true;error.value='';rows.value=[];try{if(tab.value==='defaults'){const r=await catalogDefaults();if(request===listRequest)defaults.value=r.data}else{const r=await catalogList(tab.value,{...query,pageNum:page.value,pageSize:size.value});if(request===listRequest){rows.value=r.rows;total.value=r.total}}}catch(e){if(request===listRequest)error.value=e.message}finally{if(request===listRequest)loading.value=false}}
function search(){page.value=1;loadList()}
function changeTab(){Object.assign(query,{name:'',kind:'',status:'',providerId:''});page.value=1;total.value=0;loadList()}
async function searchOptions(key,name=''){const dialogID=dialogRequest;const request=(optionRequests[key]||0)+1;optionRequests[key]=request;optionLoading.value=true;try{const provider=key==='providerId';const r=await catalogList(provider?'providers':'models',{name,pageSize:20,...(!provider?{kind:key==='textModelId'?'text':'image',status:'enabled'}:{})});if(dialogID===dialogRequest && optionRequests[key]===request)options[key]=r.rows.map(row=>({label:`${row.name} · ${row.code}`,value:provider?row.providerId:row.modelId,profile:provider?providerProfile(row.endpoint,row.adapterKind):'',disabled:!provider && (row.providerStatus!=='enabled'||row.currentVersion==='0')}))}catch(e){if(dialogID===dialogRequest && optionRequests[key]===request)formError.value=e.message}finally{if(dialogID===dialogRequest && optionRequests[key]===request)optionLoading.value=false}}
function clearSecret(){if(form.value)form.value.secret=''}
function fieldChanged(key){if(key==='presetId')applyModelPreset(form.value,form.value.presetId);delete fieldErrors.value[key];if(key==='sourceType')clearSecret();if(key==='providerProfile')form.value.endpoint=providerProfiles[form.value.providerProfile]?.endpoint||'';if(key==='providerId'){form.value.providerProfile=(options.providerId||[]).find(o=>o.value===form.value.providerId)?.profile||'';if(!providerSupportsImages(form.value.providerProfile))form.value.kind='text'}}
function closeDialog(done){if(!saving.value){clearSecret();++dialogRequest;done()}}
async function open(action,row={}){
  const request=++dialogRequest;optionLoading.value=false
  op.value=action;formError.value='';fieldErrors.value={};form.value={id:action.startsWith('provider.')?row.providerId||'':row.modelId||'',revision:row.revision||'',name:row.name||'',code:row.code||'',providerId:row.providerId||'',kind:row.kind||'text',visible:!!row.visible,sort:row.sort||0,providerProfile:providerProfile(row.providerEndpoint||row.endpoint,row.providerAdapterKind||row.adapterKind)||'qwen',region:row.region||'global',presetId:'',textApi:'',imageQuality:'',imageResponse:'',sourceType:'encrypted',secret:'',envName:'',endpoint:'https://dashscope.aliyuncs.com',status:row.status==='enabled'?'disabled':'enabled',reason:'',officialModelId:row.kind==='image'?'qwen-image-2.1-turbo':'qwen-flash',timeoutSeconds:300,maxInputBytes:32000,maxOutputTokens:2048,maxPromptChars:1200,maxImages:4,maxReferenceImages:3,ratios:[...ratios],costInputYuan:'',costOutputYuan:'',costImageYuan:'',pointInput:'0',pointOutput:'0',pointImage:'0',textModelId:row.textModelId||'',imageModelId:row.imageModelId||''};dialog.value=true
  if(action==='provider.update')Object.assign(form.value,{endpoint:row.endpoint,originalEndpoint:row.endpoint,canEditEndpoint:row.adapterKind==='openai-compatible-v1'&&has('podAdmin:model:edit')})
  if(action==='model.create')await searchOptions('providerId')
  if(action==='model.version' && (!row.currentVersion || row.currentVersion==='0')){const preset=modelPresets.find(p=>p.code===row.code&&p.provider===form.value.providerProfile);if(preset)applyModelPreset(form.value,preset.code)}
  if(action==='model.version' && (!row.currentVersion || row.currentVersion==='0')){const choices=modelExamplesFor(form.value.providerProfile,form.value.kind);form.value.officialModelId=choices.find(id=>(row.code||'').replace(/[._-]/g,'').toLowerCase().endsWith(id.split('/').pop().replace(/[._-]/g,'').toLowerCase()))||choices[0]||''}
  if(action==='defaults.update'){await Promise.all([searchOptions('textModelId'),searchOptions('imageModelId')]);for(const key of ['textModelId','imageModelId']){if(request!==dialogRequest)return;const id=form.value[key];if(id && !(options[key]||[]).some(o=>o.value===id)){try{const r=await catalogGet('models',id);if(request!==dialogRequest)return;(options[key]||=[]).push({label:r.data.name,value:id,disabled:r.data.status!=='enabled'||r.data.providerStatus!=='enabled'})}catch(e){if(request===dialogRequest)formError.value=e.message}}}}
  if(action==='model.version' && row.currentVersion && row.currentVersion!=='0'){try{const r=await catalogVersions(row.modelId,{pageSize:1});const v=r.rows[0];if(v && request===dialogRequest){for(const [ratio,size] of Object.entries(v.capabilities.imageSizes||{}))form.value['size_'+ratio]=size;Object.assign(form.value,v.capabilities,{officialModelId:v.officialModelId,timeoutSeconds:v.timeoutSeconds,costInputYuan:microsToYuan(v.costRule.inputPerMillion),costOutputYuan:microsToYuan(v.costRule.outputPerMillion),costImageYuan:microsToYuan(v.costRule.perImage),pointInput:v.pointRule.inputPerMillion,pointOutput:v.pointRule.outputPerMillion,pointImage:v.pointRule.perImage})}}catch(e){if(request===dialogRequest)formError.value=e.message}}
}
function forgetPending(){pending.value=null;try{sessionStorage.removeItem(pendingKey)}catch{ElMessage.warning('操作已完成，但浏览器记录未清除；下次可再次核对原编号')}}
async function submit(){if(saving.value)return;formError.value='';fieldErrors.value=catalogFieldErrors(op.value,form.value);if(Object.keys(fieldErrors.value).length){formError.value=fieldErrors.value.endpoint?'请检查接口地址':fieldErrors.value.code?'请检查固定编码':'请检查标出的价格与点数';await nextTick();document.getElementById('catalog-field-'+Object.keys(fieldErrors.value)[0])?.focus();return}let w;try{w=catalogPayload(op.value,form.value);if(!w.data.reason.trim())throw new Error('请填写操作原因')}catch(e){formError.value=e.message;return}if(pending.value && (pending.value.path!==w.path||pending.value.op!==op.value)){formError.value='先核对原操作，不能更换目标或操作类型';return}const meta=pending.value||pendingMetadata(op.value,w,form.value,labels[op.value]);w.data.requestId=meta.requestId;try{sessionStorage.setItem(pendingKey,JSON.stringify(meta))}catch{formError.value='浏览器无法保存操作编号，本次尚未提交；请检查存储权限后重试';clearSecret();w.data.secret='';return}pending.value=meta;saving.value=true;try{await catalogWrite(w.method,w.path,w.data);forgetPending();dialog.value=false;ElMessage.success('已保存');await loadList()}catch(e){formError.value=e.message;if(e.code>=400 && e.code<500){try{await catalogAction(meta.requestId);forgetPending();dialog.value=false;ElMessage.success('原操作已完成');await loadList()}catch(checkError){if(checkError.code===404)forgetPending()}}}finally{clearSecret();w.data.secret='';saving.value=false}}
async function checkPending(){if(!pending.value)return;checking.value=true;error.value='';try{await catalogAction(pending.value.requestId);forgetPending();dialog.value=false;clearSecret();ElMessage.success('原操作已完成');await loadList()}catch(e){error.value=e.code===404?'尚无已完成记录；保留原编号，重填原内容核对或重试，不要另建请求。':e.message}finally{checking.value=false}}
async function recoverPending(){const p=pending.value;if(!p)return;try{try{await catalogAction(p.requestId);forgetPending();ElMessage.success('原操作已完成');await loadList();return}catch(e){if(e.code!==404)throw e}let row={};if(p.op==='defaults.update')row=(await catalogDefaults()).data;else if(!p.op.endsWith('.create'))row=(await catalogGet(p.op.startsWith('provider')?'providers':'models',p.id)).data;await open(p.op,row);form.value.id=p.id;form.value.revision=p.revision;if(p.kind)form.value.kind=p.kind;if(p.status)form.value.status=p.status}catch(e){error.value=e.message}}
async function showVersions(row){versionModel.value=row;versionPage.value=1;versionTotal.value=0;versionsOpen.value=true;await loadVersions()}
async function loadVersions(){const request=++versionRequest;versionsLoading.value=true;versionsError.value='';versions.value=[];try{const r=await catalogVersions(versionModel.value.modelId,{pageNum:versionPage.value,pageSize:versionSize.value});if(request===versionRequest){versions.value=r.rows;versionTotal.value=r.total}}catch(e){if(request===versionRequest)versionsError.value=e.message}finally{if(request===versionRequest)versionsLoading.value=false}}
async function checkModel(row){try{const r=await catalogCheck(row.modelId);ElMessage.success(r.data.message)}catch(e){error.value=e.message}}
onMounted(loadList)
onBeforeUnmount(()=>{clearSecret();++dialogRequest;++listRequest;++versionRequest;for(const key in optionRequests)++optionRequests[key]})
</script>
